def parse_ids(pos):
    if not pos:return None
    s=pos[0]
    if not re.fullmatch(r'[\d,-]+',s):return None
    out=set()
    for bit in s.split(','):
        if '-' in bit:
            a,b=(bit.split('-',1)+[''])[:2]
            try:out.update(range(int(a),int(b)+1))
            except ValueError:pass
        else:
            try:out.add(int(bit))
            except ValueError:pass
    return out

def render(lines, selected, flags, opts, footer=True):
    full = any(re.search(r'(?<!\S)(?:\d{4}-\d\d-\d\d|due:)', line) for _,line in selected)
    header=' # D P Created Finished Due        Subject' if full else ' # D P Created Finished Due Subject'
    rows=[]
