import calendar
import datetime as dt
import re


def _add_months(day, amount):
    idx=day.year*12+day.month-1+amount
    y,m=divmod(idx,12);m+=1
    return dt.date(y,m,min(day.day,calendar.monthrange(y,m)[1]))

def _delta(token):
    if not token:return 0,'d'
    m=re.fullmatch(r'([+-]?\d*)([dwmy]?)',token)
    if not m:return None
    return (int(m[1] or ('-1' if token.startswith('-') else '1')),m[2] or 'd')

def _shift(day,n,unit):
    if unit=='d':return day+dt.timedelta(days=n)
    if unit=='w':return day+dt.timedelta(days=n*7)
    if unit=='m':return _add_months(day,n)
    return _add_months(day,n*12)

def _range(spec,today):
    strict=(spec or '').startswith('+')
    s=(spec or '1m')
    if strict:s=s[1:]
    if '..' in s:
        a,b=s.split('..',1);da=_delta(a);db=_delta(b)
        if da is None or db is None:return None
        start=_shift(today,*da) if a else today
        end=_shift(today,*db) if b else today
        return (min(start,end),max(start,end))
    d=_delta(s)
    if d is None:return None
    n,u=d
    if u in ('w','m','y') and not strict:
        if u=='w':
            base=today-dt.timedelta(days=(today.weekday()+1)%7)
            count=max(1,abs(n))
            start=base-dt.timedelta(days=7*(count-1)) if n<0 else base
            return start,start+dt.timedelta(days=7*count-1)
        months=max(1,abs(n))
        if n<0:
            first=dt.date(today.year,today.month,1)
            start=_add_months(first,-(months-1));end=dt.date(today.year,today.month,calendar.monthrange(today.year,today.month)[1])
        else:
            start=dt.date(today.year,today.month,1)
            end0=_add_months(start,months)
            end=end0-dt.timedelta(days=1)
        return start,end
    if strict:
        count=abs(n or 1)*(7 if u=='w' else 30 if u=='m' else 365 if u=='y' else 1)
        if n<0:return today-dt.timedelta(days=count-1),today
        return today,today+dt.timedelta(days=count-1)
    if n<0:return _shift(today,n,u),today
    return today,_shift(today,n,u)

